{
  "name": "spotme",
  "version": "1.2.4",
  "description": "SpotMe - gym mode for agentic coding. Works with OpenCode and Pi.",
  "author": {
    "name": "wtfzambo"
  },
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js",
    "./opencode": "./dist/opencode.js"
  },
  "files": [
    "dist",
    "src"
  ],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wtfzambo/spotme.git"
  },
  "scripts": {
    "build": "bun build src/index.ts src/opencode.ts --outdir dist --target bun",
    "typecheck": "tsc --noEmit",
    "test:packaging": "node scripts/check-packaging.mjs",
    "lint": "eslint src",
    "lint:fix": "eslint src --fix",
    "format": "prettier --write src"
  },
  "keywords": [
    "pi-package",
    "opencode-plugin",
    "spotme",
    "gym-mode",
    "coding-agent"
  ],
  "pi": {
    "extensions": [
      "./src/pi.ts"
    ],
    "image": "https://raw.githubusercontent.com/wtfzambo/spotme/refs/heads/main/imgs/spotme.png"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.0"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "@sinclair/typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "@sinclair/typebox": {
      "optional": true
    }
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": "^0.74.0",
    "@sinclair/typebox": "^0.34.0",
    "@types/bun": "^1.1.0",
    "@types/node": "^22.0.0",
    "@typescript-eslint/eslint-plugin": "8.47.0",
    "@typescript-eslint/parser": "8.47.0",
    "backlog.md": "^1.45.1",
    "eslint": "^9.39.1",
    "eslint-config-prettier": "10.1.8",
    "eslint-plugin-prettier": "^5.1.3",
    "prettier": "^3.2.4",
    "typescript": "^5.7.0",
    "typescript-eslint": "^8.47.0"
  }
}
